export interface EmailBrand { schoolName: string; logoUrl: string|null; brand: string; buttonBg: string; buttonInk: string; brandText: string; headingFontStack: string }

export async function getEmailBrand(tenantId: string): Promise<EmailBrand> {
  const admin = createAdminClient()
  const [{data: tenant}, {data: settings}, customBranding] = await Promise.all([
    admin.from('tenants').select('name, logo_url').eq('id', tenantId).maybeSingle(),
    admin.from('tenant_settings').select('setting_key, setting_value').eq('tenant_id', tenantId).in('setting_key', ['site_name','logo_url', SCHOOL_THEME_SETTING_KEY]),
    hasPlanFeature(tenantId, 'custom_branding'),
  ])
  const map = Object.fromEntries((settings??[]).map(s=>[s.setting_key, s.setting_value]))
  const schoolName = map.site_name?.value || tenant?.name || 'LMS Platform'
  const logoUrl = map.logo_url?.value || tenant?.logo_url || null
  const theme = resolveSchoolTheme(map[SCHOOL_THEME_SETTING_KEY], { customBranding })
  const PLATFORM_BRAND = '#2563eb', PLATFORM_INK = '#ffffff'
  if (!theme) return { schoolName, logoUrl, brand: PLATFORM_BRAND, buttonBg: PLATFORM_BRAND, buttonInk: PLATFORM_INK, brandText: PLATFORM_BRAND, headingFontStack: EMAIL_FONT_STACKS.structured }
  const { light } = deriveKitVars(theme.theme, theme.brand)
  const toHex_ = (css: string, fb: string) => { const rgb = parseColor(css); return rgb ? toHex(rgb) : fb }
  return {
    schoolName, logoUrl, brand: theme.brand,
    buttonBg: toHex_(light['--primary'], theme.brand),
    buttonInk: toHex_(light['--primary-foreground'], PLATFORM_INK), // ALWAYS oklch() at source — this conversion is load-bearing
    brandText: toHex_(light['--brand-text'], theme.brand),
    headingFontStack: EMAIL_FONT_STACKS[KIT_THEMES[theme.theme].typePairing],
  }
}

const EMAIL_FONT_STACKS: Record<KitTypePairingId,string> = {
  structured: "'Helvetica Neue', Helvetica, Arial, sans-serif",
  classic: "Georgia, 'Times New Roman', serif",
  friendly: "'Helvetica Neue', Helvetica, Arial, sans-serif",
  plain: "'Helvetica Neue', Helvetica, Arial, sans-serif",
}
// 3 of 4 pairings collapse to the same generic sans stack — Instrument Sans/Outfit/Public Sans/Figtree/Noto Sans have no close email-safe match; only Lora→serif reads distinct.

Uses createAdminClient() only (no headers()/getCurrentTenantId()), so it works unmodified from request context, webhooks and cron alike — call with whatever tenantId each site already has in scope.
